/**
 * @sw-package framework
 */
import type { ComponentUnit } from './model';

/** @private */
export const GENERATE_COMMAND = 'composer admin:generate-public-api';

/** @private The first line of every generated file. */
export const GENERATED_BY = `Generated by \`${GENERATE_COMMAND}\`. Do not edit.`;

/** @private The document that describes the snapshot format. */
export const FORMAT_DOCUMENT = 'technical-docs/11-code-quality/03-public-api-snapshot.md';

/**
 * @private
 *
 * The files a component consists of, each with its label in the header of a contract. A report prints the
 * label in lower case.
 */
export function sourceFiles({ source, sfc, template }: ComponentUnit): [label: string, file: string][] {
    return [
        ['Source', source],
        ...(sfc === null ? [] : [['SFC', sfc] as [string, string]]),
        ...(template === null ? [] : [['Template', template] as [string, string]]),
    ];
}
